<?php require_once __DIR__.'/app_private/bootstrap.php';$token=$_GET['token']??'';$st=db()->prepare('SELECT i.*,c.name customer_name,u.business_name owner_name,s.business_logo,s.bank_details,s.currency,s.currency_symbol,s.currency_symbol_position,s.currency_decimal_separator,s.currency_thousands_separator,s.currency_decimals FROM invoices i JOIN customers c ON c.id=i.customer_id JOIN users u ON u.id=i.user_id LEFT JOIN settings s ON s.user_id=i.user_id WHERE i.public_token=?');$st->execute([$token]);$i=$st->fetch();if(!$i){http_response_code(404);exit('Invoice not found.');}$st=db()->prepare('SELECT * FROM invoice_items WHERE invoice_id=?');$st->execute([$i['id']]);$items=$st->fetchAll();$fm=fn(float $amount)=>format_money($amount,$i);page_header('Invoice '.$i['invoice_number'],true);?><article class="doc"><?php $logo=logo_src($i['business_logo']??''); if($logo):?><img class="doc-logo" src="<?=e($logo)?>" alt="<?=e($i['owner_name'])?> logo"><?php endif;?><div class="doc-brandname"><?=e($i['owner_name'])?></div><h1>Invoice <?=e($i['invoice_number'])?></h1><p><strong>From:</strong> <?=e($i['owner_name'])?><br><strong>For:</strong> <?=e($i['customer_name'])?></p><div class="mobile-table"><table><thead><tr><th>Description</th><th>Qty</th><th>Unit price</th><th>Total</th></tr></thead><tbody><?php foreach($items as $x):?><tr><td><?=e($x['description'])?></td><td><?=e((string)$x['qty'])?></td><td><?=$fm((float)$x['unit_price'])?></td><td><?=$fm((float)$x['line_total'])?></td></tr><?php endforeach;?></tbody></table></div><div class="totals"><div><span>Subtotal</span><span><?=$fm((float)$i['subtotal'])?></span></div><div><span>Tax</span><span><?=$fm((float)$i['tax'])?></span></div><div class="grand"><span>Total</span><span><?=$fm((float)$i['total'])?></span></div></div><p><strong>Due:</strong> <?=e($i['due_date']??'-')?></p><?php if($i['bank_details']):?><h3>Bank transfer details</h3><p><?=nl2br(e($i['bank_details']))?></p><?php endif;?><p class="muted">This service does not process or verify payments. Payment arrangements are between you and the business.</p></article><?php page_footer();?>
